{"success": true, "data": {"stdout": """"Null distribution construction from alpha=0.00 data.

Uses alpha=0.00 runs (no synthetic contamination) to build the empirical
distribution of consensus scores under H0. Supports both uniform and
weighted consensus modes. Per-method FPR profiles are computed for
inverse-FPR weighting.
"""

import numpy as np
from pathlib import Path

from .methods import (METHOD_NAMES, METRIC_PAIRS, load_5method_results,
                      extract_method_significance)


class NullDistribution:
    """Empirical null distribution for MMCT consensus scores."""

    def __init__(self, null_dirs, n_bootstrap=10000, seed=42):
        """
        Args:
            null_dirs: list of paths to alpha=0.00 experiment directories
            n_bootstrap: bootstrap resamples for p-value CI
            seed: random seed for reproducibility
        """
        self.null_dirs = null_dirs
        self.n_bootstrap = n_bootstrap
        self.seed = seed

        self._per_pair_sigs = {}
        self._load_null_data()
        self._compute_fpr_profile()
        self._build_distributions()

    def _load_null_data(self):
        for d in self.null_dirs:
            results = load_5method_results(d)
            for canary, downstream in METRIC_PAIRS:
                key = (canary, downstream)
                if key not in self._per_pair_sigs:
                    self._per_pair_sigs[key] = {"forward": [], "reverse": []}

                fwd = extract_method_significance(
                    results, canary, downstream, "forward")
                rev = extract_method_significance(
                    results, canary, downstream, "reverse")
                self._per_pair_sigs[key]["forward"].append(fwd)
                self._per_pair_sigs[key]["reverse"].append(rev)

    def _compute_fpr_profile(self):
        """Per-pair per-method FPR and global per-method FPR from null data."""
        self.fpr_profile = {}
        self.global_fpr = {}

        method_sig_counts = {m: 0 for m in METHOD_NAMES}
        total_obs = 0

        for key in METRIC_PAIRS:
            key = tuple(key)
            sigs_list = self._per_pair_sigs[key]["forward"]
            n_seeds = len(sigs_list)
            pair_fpr = {}
            for method in METHOD_NAMES:
                n_sig = sum(1 for s in sigs_list if s[method])
                pair_fpr[method] = n_sig / n_seeds if n_seeds > 0 else 0.0
                method_sig_counts[method] += n_sig
            self.fpr_profile[key] = pair_fpr
            total_obs += n_seeds

        for method in METHOD_NAMES:
            self.global_fpr[method] = (method_sig_counts[method] / total_obs
                                       if total_obs > 0 else 0.0)

    def get_weights(self, pair_key, epsilon=0.01):
        """Inverse-FPR weights: w_k = 1 / max(FPR_k, epsilon)."""
        fpr = self.fpr_profile.get(tuple(pair_key), {})
        return {m: 1.0 / max(fpr.get(m, 0.0), epsilon)
                for m in METHOD_NAMES}

    def consensus_score_uniform(self, sig_dict):
        """Count of significant methods (0..5)."""
        return sum(1 for m in METHOD_NAMES if sig_dict.get(m, False))

    def consensus_score_weighted(self, sig_dict, weights):
        """Normalized weighted consensus: sum(w_k * I_k) / sum(w_k)."""
        total_w = sum(weights[m] for m in METHOD_NAMES)
        if total_w == 0:
            return 0.0
        return (sum(weights[m] * (1.0 if sig_dict.get(m, False) else 0.0)
                    for m in METHOD_NAMES) / total_w)

    def _build_distributions(self):
        """Build pooled null score arrays for uniform and weighted modes."""
        uniform_fwd, uniform_rev = [], []
        weighted_fwd, weighted_rev = [], []

        self._null_sig_vectors_fwd = []
        self._null_sig_vectors_rev = []

        for key in METRIC_PAIRS:
            key = tuple(key)
            weights = self.get_weights(key)

            for sig in self._per_pair_sigs[key]["forward"]:
                uniform_fwd.append(self.consensus_score_uniform(sig))
                weighted_fwd.append(
                    self.consensus_score_weighted(sig, weights))
                self._null_sig_vectors_fwd.append((key, sig))

            for sig in self._per_pair_sigs[key]["reverse"]:
                uniform_rev.append(self.consensus_score_uniform(sig))
                weighted_rev.append(
                    self.consensus_score_weighted(sig, weights))
                self._null_sig_vectors_rev.append((key, sig))

        self.null_uniform_fwd = np.array(uniform_fwd)
        self.null_uniform_rev = np.array(uniform_rev)
        self.null_weighted_fwd = np.array(weighted_fwd)
        self.null_weighted_rev = np.array(weighted_rev)

    def p_value(self, observed_score, weighted=False, direction="forward"):
        """Compute p-value = P(C_null >= C_obs) with bootstrap CI.

        Returns (p_value, ci_lower, ci_upper).
        """
        if weighted:
            null = (self.null_weighted_fwd if direction == "forward"
                    else self.null_weighted_rev)
        else:
            null = (self.null_uniform_fwd if direction == "forward"
                    else self.null_uniform_rev)

        n = len(null)
        p = (np.sum(null >= observed_score) + 1) / (n + 1)

        rng = np.random.default_rng(self.seed)
        boot_p = np.empty(self.n_bootstrap)
        for i in range(self.n_bootstrap):
            sample = rng.choice(null, size=n, replace=True)
            boot_p[i] = (np.sum(sample >= observed_score) + 1) / (n + 1)

        ci_lo = float(np.percentile(boot_p, 2.5))
        ci_hi = float(np.percentile(boot_p, 97.5))
        return float(p), ci_lo, ci_hi

    def to_dict(self):
        """Serialize for JSON output."""
        return {
            "null_dirs": self.null_dirs,
            "n_null_observations": int(len(self.null_uniform_fwd)),
            "n_seeds_per_pair": {
                f"{k[0]}__{k[1]}": len(self._per_pair_sigs[k]["forward"])
                for k in self._per_pair_sigs},
            "global_fpr": {m: round(v, 4) for m, v in self.global_fpr.items()},
            "per_pair_fpr": {
                f"{k[0]}__{k[1]}": {m: round(v, 4) for m, v in fpr.items()}
                for k, fpr in self.fpr_profile.items()},
            "null_scores_uniform_fwd": self.null_uniform_fwd.tolist(),
            "null_scores_uniform_rev": self.null_uniform_rev.tolist(),
            "null_scores_uniform_stats": {
                "mean": round(float(self.null_uniform_fwd.mean()), 4),
                "std": round(float(self.null_uniform_fwd.std()), 4),
                "min": int(self.null_uniform_fwd.min()),
                "max": int(self.null_uniform_fwd.max()),
            },
            "null_scores_weighted_fwd": [round(x, 6) for x in
                                          self.null_weighted_fwd.tolist()],
            "null_scores_weighted_stats": {
                "mean": round(float(self.null_weighted_fwd.mean()), 4),
                "std": round(float(self.null_weighted_fwd.std()), 4),
                "min": round(float(self.null_weighted_fwd.min()), 4),
                "max": round(float(self.null_weighted_fwd.max()), 4),
            },
            "n_bootstrap": self.n_bootstrap,
        }
